4	
5	func TestTotal(t *testing.T) {
6		items := []Item{{"pen", 150, 2}, {"book", 1000, 1}}
7		if got := Total(items, 0); got != 1300 {
8			t.Errorf("no discount: got %d, want 1300", got)
9		}
10		if got := Total(items, 10); got != 1170 {
11			t.Errorf("10%% discount: got %d, want 1170", got)
12		}
13	}
