1	package shop
2	
3	import "sort"
4	
5	func Mean(xs []int) float64 {
6		if len(xs) == 0 {
7			return 0
8		}
9		sum := 0
10		for _, x := range xs {
11			sum += x
12		}
13		return float64(sum / len(xs))
14	}
15	
16	func Median(xs []float64) float64 {
17		if len(xs) == 0 {
18			return 0
19		}
20		s := append([]float64(nil), xs...)
21		sort.Float64s(s)
22		n := len(s)
23		if n%2 == 1 {
24			return s[n/2]
25		}
26		return (s[n/2-1] + s[n/2]) / 2
27	}
