3	import "strings"
4	
5	func WordCount(s string) int {
6		return len(strings.Fields(s))
7	}
8	
9	func Truncate(s string, n int) string {
10		if len(s) <= n {
11			return s
12		}
13		return s[:n-1] + "…"
14	}
