4	
5	func TestWordCount(t *testing.T) {
6		if got := WordCount("  one two\tthree\n"); got != 3 {
7			t.Errorf("got %d, want 3", got)
8		}
9	}
10	
11	func TestTruncate(t *testing.T) {
12		cases := []struct {
13			in   string
14			n    int
15			want string
16		}{
17			{"hello", 5, "hello"},
18			{"hello world", 5, "hell…"},
19			{"привет мир", 6, "приве…"},
20		}
21		for _, c := range cases {
22			if got := Truncate(c.in, c.n); got != c.want {
23				t.Errorf("Truncate(%q, %d) = %q, want %q", c.in, c.n, got, c.want)
24			}
25		}
26	}
